viz.option:
option = {
  title: {
    text: 'Workstation Cycle Time Distribution',
    subtext: 'Production Line QC — seconds per part',
    left: 'center'
  },
  tooltip: {
    trigger: 'item',
    axisPointer: { type: 'shadow' }
  },
  xAxis: {
    type: 'category',
    name: 'Workstation',
    axisLabel: { rotate: 10 }
  },
  yAxis: {
    type: 'value',
    name: 'Cycle Time (s)',
    splitArea: { show: true }
  },
  series: []
};

pre.code:
series: [
  {
    name: 'Takt Time Target',
    type: 'line',
    markLine: {
      symbol: 'none',
      data: [{ type: 'average', name: 'Avg' }]
    },
    data: []
  }
]

yAxis: {
  type: 'value',
  name: 'Cycle Time (s)',
  splitArea: { show: true }
},
series: [
  {
    type: 'boxplot',
    markLine: {
      data: [{ yAxis: 60, name: 'SLA target: 60 s', label: { position: 'end' } }],
      lineStyle: { color: '#d9534f', type: 'dashed' }
    }
  }
]

viz.option:
option = {
  title: {
    text: 'Cycle Times with SLA Reference Line',
    left: 'center'
  },
  tooltip: {
    trigger: 'item',
    axisPointer: { type: 'shadow' }
  },
  xAxis: {
    type: 'category',
    name: 'Workstation',
    axisLabel: { rotate: 10 }
  },
  yAxis: {
    type: 'value',
    name: 'Cycle Time (s)',
    splitArea: { show: true }
  },
  series: [
    {
      type: 'boxplot',
      markLine: {
        silent: true,
        data: [{ yAxis: 60, name: 'SLA 60 s' }],
        lineStyle: { color: '#d9534f', type: 'dashed', width: 2 },
        label: { position: 'end', formatter: 'SLA 60 s', color: '#d9534f' }
      }
    }
  ]
};
